import React from 'react';

interface WhatsAppButtonProps {
  phoneNumber: string;
  serviceName: string;
  currentUrl: string;
}

export const WhatsAppContact = ({ phoneNumber, serviceName, currentUrl }: WhatsAppButtonProps) => {
  const message = `Hi, I am interested in ${serviceName}. I was looking at this page: ${currentUrl}`;
  const encodedMessage = encodeURIComponent(message);
  const whatsappUrl = `https://wa.me/${phoneNumber}?text=${encodedMessage}`;

  return (
    <a 
      href={whatsappUrl} 
      target="_blank" 
      rel="noopener noreferrer"
      className="bg-green-500 text-white px-6 py-3 rounded-lg font-bold"
    >
      Inquire via WhatsApp
    </a>
  );
};
